		/** 
		 * Tests creating a new KPI.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a KPI");

			StringBuilder msg = new StringBuilder( "-- Failed to create a KPI" );

			try {            
				KPI entity = KPIService.getKPIInstance().createKPI( generateNewEntity() );
				thePrimaryKey = entity.getKPIId();
				LOGGER.info( "-- Successfully created a KPI with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a KPI. 
		 */
		public KPI testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created KPI" );

			KPI entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read KPI with primary key" );
			msg.append( thePrimaryKey );
			
			KPIFetchOneSummary fetchOneSummary = new KPIFetchOneSummary( thePrimaryKey );

			try {
				entity = KPIService.getKPIInstance().getKPI( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found KPI " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a KPI.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a KPI." );

			StringBuilder msg = new StringBuilder( "Failed to update a KPI : " );        
			KPI entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created KPI." );

				// for use later on...
				thePrimaryKey = entity.getKPIId();

				KPIService proxy = KPIService.getKPIInstance();            
				proxy.updateKPI( entity );   

				LOGGER.info( "-- Successfully saved KPI - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a KPI.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created KPI." );

			try{
			    KPI entity = testRead(); 
				KPIService.getKPIInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted KPI with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete KPI with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all KPIs.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of KPIs:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all KPI : " );        
			List<KPI> collection  = null;

			try {
				// call the static get method on the KPIService
				collection = KPIService.getKPIInstance().getAllKPI();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					KPI entity = null;            
					Iterator<KPI> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getKPIId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/**
		 * Assigns a common log handler for each test class in the suite
		 * @param		handler	Handler
		 * @return		KPITest
		 */
		public KPITest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated KPI
		 * 
		 * @return KPI
		 */
		protected KPI generateNewEntity() {
			KPI entity = new KPI( null,  java.math.BigDecimal.ZERO,  null,  MetricType.values()[0] );
			
			return( entity );
		}

		//-----------------------------------------------------
